/// <summary>
/// The <c>AVAWHSProcessGuideCoilCalculatorController</c> class is the controller class to run coil calculator
/// </summary>
[
    WHSWorkExecuteModeAttribute(WHSWorkExecuteMode::AVACoilCalculator)
]
class AVAWHSProcessGuideCoilCalculatorController extends ProcessGuideController
{
}

Method.Source:
protected final ProcessGuideNavigationRoute initializeNavigationRoute()
{
    var                 navigationRoute = new ProcessGuideNavigationRoute();
    WhsrfPassthrough    pass;

    if (this.parmSessionState()
     && this.parmSessionState().parmPass()
     && this.parmSessionState().parmPass().parmMenuItem())
    {
        pass = this.parmSessionState().parmPass();

        navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorResultStep));

        if (WHSRFMenuItemTable::find(pass.parmMenuItem()).AVAAllowPostAdjustment == NoYes::Yes)
        {
            navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptCoilCalculatorResultStep), classStr(AVAWHSProcessGuidePromptPostCoilCalculatorStep));
            navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptPostCoilCalculatorStep), classStr(AVAWHSProcessGuidePostCoilCalculatorStep));

            if (pass.avaParmCoilWeight() > 0 )
            {
                navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePostCoilCalculatorStep), classStr(InventProcessGuidePromptAndConfirmAdjustInStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuidePromptAndConfirmAdjustInStep), classStr(InventProcessGuideCaptureCatchWeightTagAdjustInStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuideCaptureCatchWeightTagAdjustInStep), classStr(InventProcessGuideDoAdjustInStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuideDoAdjustInStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep));
            }
            else if (pass.avaParmCoilWeight() < 0 )
            {
                navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePostCoilCalculatorStep), classStr(InventProcessGuidePromptAndConfirmAdjustOutStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuidePromptAndConfirmAdjustOutStep), classStr(InventProcessGuidePromptAndConfirmQtyAdjustOutStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuidePromptAndConfirmQtyAdjustOutStep), classStr(InventProcessGuideCaptureCatchWeightTagAdjustOutStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuideCaptureCatchWeightTagAdjustOutStep), classStr(InventProcessGuideStartAdjustOutStep));
                navigationRoute.addFollowingStep(classStr(InventProcessGuideStartAdjustOutStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep));
            }
            else
            {
                navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePostCoilCalculatorStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep));
            }
        }
        else
        {
            navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptCoilCalculatorResultStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep));
        }
    }
    else
    {
        navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorResultStep));
        navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptCoilCalculatorResultStep), classStr(AVAWHSProcessGuidePromptCoilCalculatorDataStep));
    }




    return navigationRoute;
}
